deps=cfg["workspace"]["dependencies"]
names=list(deps)
def cur(v):
    return v if isinstance(v,str) else v.get("version","?")
out=[]
for n in names:
    try:
        with urllib.request.urlopen(f"https://crates.io/api/v1/crates/{n}",timeout=15) as r:
            d=json.load(r)
        latest=d["crate"]["max_stable_version"]
    except Exception as e:
        latest=f"ERR {e}"
    out.append((n,cur(deps[n]),latest))
for n,c,l in out:
    def major(s): 
        m=re.match(r"(\d+)\.?(\d+)?",s); return m.groups() if m else (None,None)
    cm=major(c); lm=major(str(l))
    flag=""
    if not str(l).startswith("ERR"):
        if cm[0]!=lm[0]: flag="  <== MAJOR"
        elif (cm[1] or "0")!=(lm[1] or "0"): flag="  <- minor"
    print(f"{n:20} {c:35} {l}{flag}")
