    fn every_export_form_lands_in_the_right_lexed_export_variant() {
        // oxc 0.151 splits `export { X }`, `export { X } from "y"`, and
        // `export const X` into three AST nodes handled by three visitors.
        // Pin the exact set, not just that each variant appears somewhere:
        // a specifier list silently classified as a re-export (or the reverse)
        // would still satisfy a presence check.
        let source = r#"
            const Local = 1;
            export { Local };
            export { Button } from "./button";
            export type { ButtonProps } from "./button";
            export * from "./types";
            export interface CardProps { a: string }
            export type Size = "sm";
            export enum Color { Red }
            export const VERSION = "1";
        "#;
        let data = parse_file(Utf8Path::new("/test/index.ts"), source);

        let mut locals: Vec<(&str, bool)> = data
            .exports
            .iter()
            .filter_map(|e| match e {
                LexedExport::LocalDeclaration { name, is_type_only } => Some((name.as_str(), *is_type_only)),
                _ => None,
            })
            .collect();
        locals.sort();
