1	//! DTS cache — persists parsed `SourceData` across runs to avoid re-parsing unchanged .d.ts files.
2	//!
3	//! Cache validity is based on a content hash of the file's actual bytes, not
4	//! mtime/size (see `CacheKey`'s doc comment for why that was replaced).
5	//! Schema version bumps automatically invalidate the entire cache.
6	//!
7	//! The cache never panics — load failures degrade gracefully to an empty
8	//! state, and save failures are reported via a `Diagnostic` (see
9	//! `save_to_disk`) rather than swallowed.
10	
11	use camino::{Utf8Path, Utf8PathBuf};
12	use dashmap::DashMap;
13	use serde::{Deserialize, Serialize};
14	use std::hash::Hasher;
15	
16	use crate::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity, SourceData};
17	
18	/// Bump this whenever `SourceData`'s field list or field order changes.
19	/// Serialization is via plain `rmp_serde::to_vec`/`from_slice` — MessagePack's
20	/// *positional* (not named-map) struct encoding — so inserting a field
21	/// anywhere but the very end shifts every subsequent field's decode position
22	/// for any cache entry written before the change. A same-shaped field
23	/// addition (e.g. another `FxHashMap<String, Vec<X>>`) wouldn't even fail
24	/// loudly; it would decode as plausible-looking but wrong data. `const_arrays`
25	/// (added mid-struct, not appended) is exactly this case — this bump covers it.
26	/// Also bumped for the mtime+size -> content-hash key change (P0-2 fix):
27	/// `SerializableCacheKey`'s own shape changed, so pre-existing on-disk cache
28	/// files must be discarded rather than misread under the new field layout.
29	/// Also bumped when the extractor produces different `SourceData` for byte-identical
30	/// input — the content-hash key can't notice that, so a stale entry would be served
31	/// forever (v4: `LiteralUnion` alias members are stored bare instead of quote-wrapped).
32	const CACHE_SCHEMA_VERSION: u32 = 4;
33	
34	// ─── Internal key type ────────────────────────────────────────────────────────
35	
36	/// Keyed by a hash of the file's actual byte content, not `(size, mtime)`.
37	///
38	/// The prior mtime+size scheme had a documented staleness gap (P0-2): on
39	/// filesystems/environments with coarse mtime resolution (network FS,
40	/// container overlay FS, or simply two edits landing in the same clock
41	/// tick), an edit completing within the same tick and producing a
42	/// same-length file was indistinguishable from the original — a stale
43	/// `SourceData` was served with no signal anything was wrong. A content hash
44	/// closes this gap exactly: two different byte sequences essentially never
45	/// hash to the same 64-bit `FxHasher` value (birthday-bound collision risk
46	/// is negligible at this cache's `MAX_CACHE_ENTRIES` scale), and identical
47	/// bytes always hash identically regardless of mtime/clock granularity.
48	/// This trades away the old stat-only check's near-zero I/O cost — computing
49	/// the hash requires the file's content, not just its metadata — but every
50	/// call site already reads the full file on a miss to parse it anyway; `get`
51	/// and `insert` both take that same content as a parameter instead of
52	/// re-deriving a (now-unreliable) proxy for it, so no call site pays for an
53	/// extra read this fix didn't already need.
54	#[derive(Hash, Eq, PartialEq, Clone)]
55	struct CacheKey {
56	    path: Utf8PathBuf,
57	    content_hash: u64,
58	}
59	
60	fn hash_content(content: &str) -> u64 {
61	    let mut hasher = rustc_hash::FxHasher::default();
62	    hasher.write(content.as_bytes());
63	    hasher.finish()
64	}
65	
66	// ─── Serializable surrogate ───────────────────────────────────────────────────
67	
68	#[derive(Serialize, Deserialize)]
69	struct SerializableCacheKey {
70	    path: String,
71	    content_hash: u64,
72	}
73	
74	impl From<&CacheKey> for SerializableCacheKey {
75	    fn from(k: &CacheKey) -> Self {
76	        Self { path: k.path.to_string(), content_hash: k.content_hash }
77	    }
78	}
79	
80	impl From<SerializableCacheKey> for CacheKey {
81	    fn from(k: SerializableCacheKey) -> Self {
82	        Self { path: Utf8PathBuf::from(k.path), content_hash: k.content_hash }
83	    }
84	}
85	
86	// ─── DtsCache ────────────────────────────────────────────────────────────────
87	
88	/// Maximum number of cached `.d.ts` entries allowed in memory/on disk.
89	const MAX_CACHE_ENTRIES: usize = 5000;
90	
91	/// Thread-safe DTS parse-result cache.
92	///
93	/// Keyed by `(path, content_hash)` — if the file's content hasn't changed,
94	/// the cached `SourceData` is returned directly without re-parsing.
95	pub struct DtsCache {
96	    store: DashMap<CacheKey, SourceData>,
97	    cache_dir: Utf8PathBuf,
98	    dirty: std::sync::atomic::AtomicBool,
99	}
100	
101	impl DtsCache {
102	    /// Load cache from disk.
103	    ///
104	    /// On any error (missing dir, schema mismatch, corrupt data) the cache
105	    /// starts empty — subsequent `insert` calls will repopulate it.
106	    ///
107	    /// `cache_dir` defaults to `node_modules/.cache/oxc-react-docgen/` relative
108	    /// to the current working directory.
109	    pub fn load_from_disk(cache_dir: Option<&Utf8Path>) -> Self {
110	        let dir = cache_dir
111	            .map(|p| p.to_owned())
112	            .unwrap_or_else(|| Utf8PathBuf::from("node_modules/.cache/oxc-react-docgen"));
113	
114	        let store = Self::try_load(&dir).unwrap_or_default();
115	        Self { store, cache_dir: dir, dirty: std::sync::atomic::AtomicBool::new(false) }
116	    }
117	
118	    fn try_load(dir: &Utf8Path) -> Option<DashMap<CacheKey, SourceData>> {
119	        // Check schema version via manifest first.
120	        let manifest_path = dir.join("manifest.json");
121	        let manifest_bytes = std::fs::read_to_string(manifest_path.as_std_path()).ok()?;
122	        let manifest: serde_json::Value = serde_json::from_str(&manifest_bytes).ok()?;
123	
124	        let schema = manifest["schema"].as_u64()?;
125	        if schema != CACHE_SCHEMA_VERSION as u64 {
126	            // Schema changed — discard entire cache.
127	            return None;
128	        }
129	
130	        let data_path = dir.join("dts-v1.msgpack");
131	        let bytes = std::fs::read(data_path.as_std_path()).ok()?;
132	
133	        let entries: Vec<(SerializableCacheKey, SourceData)> = rmp_serde::from_slice(&bytes).ok()?;
134	
135	        let map = DashMap::with_capacity(entries.len());
136	        for (k, v) in entries {
137	            map.insert(CacheKey::from(k), v);
138	        }
139	        Some(map)
140	    }
141	
142	    /// Look up cached `SourceData` for `path`, given its current content.
143	    ///
144	    /// Returns `None` if the file is not cached or its content hash has
145	    /// changed. `content` is a parameter rather than read internally because
146	    /// every call site already reads the file to parse it on a miss — taking
147	    /// content here means neither a hit nor a miss ever reads the file twice.
148	    pub fn get(&self, path: &Utf8Path, content: &str) -> Option<SourceData> {
149	        let key = self.key_for(path, content);
150	        self.store.get(&key).map(|v| v.clone())
151	    }
152	
153	    /// Insert `data` into the cache, keyed by `path` + a hash of `content`.
154	    pub fn insert(&self, path: &Utf8Path, content: &str, data: SourceData) {
155	        let key = self.key_for(path, content);
156	        // Evict extra entries if cache size exceeds MAX_CACHE_ENTRIES
157	        if self.store.len() >= MAX_CACHE_ENTRIES {
158	            let keys_to_evict: Vec<CacheKey> = self.store.iter().take(100).map(|r| r.key().clone()).collect();
159	            for k in keys_to_evict {
160	                self.store.remove(&k);
161	            }
162	        }
163	        self.store.insert(key, data);
164	        self.dirty.store(true, std::sync::atomic::Ordering::Relaxed);
165	    }
166	
167	    /// Persist the cache to disk atomically (temp file + rename).
168	    ///
169	    /// Skips writing if the cache is clean (no inserts since load). Never
170	    /// panics — on failure, returns a `Diagnostic` describing what went
171	    /// wrong (cache persistence is best-effort and must not fail the
172	    /// extraction run) instead of failing silently. Severity is `Info`, not
173	    /// `Warning`: a `Warning` here would flip `docgen check --strict`'s exit
174	    /// code to 1 purely because caching failed, even though extraction
175	    /// output itself is entirely correct — the exact class of spurious
176	    /// exit-code flip this project has already fixed once (see the
177	    /// resolver's discarded-return-type-resolution fix).
178	    pub fn save_to_disk(&self) -> Option<Diagnostic> {
179	        if !self.dirty.load(std::sync::atomic::Ordering::Relaxed) {
180	            return None;
181	        }
182	        self.try_save().err().map(|reason| Diagnostic {
183	            severity: DiagnosticSeverity::Info,
184	            message: format!("Failed to persist the DTS cache to '{}': {reason}", self.cache_dir),
185	            file: None,
186	            line: None,
187	            column: None,
188	            help: Some("Check that the cache directory is writable. Extraction still succeeded; only caching for the next run was affected.".into()),
189	            code: DiagnosticCode::IoError,
190	        })
191	    }
192	
193	    fn try_save(&self) -> Result<(), String> {
194	        std::fs::create_dir_all(self.cache_dir.as_std_path()).map_err(|e| e.to_string())?;
195	
196	        // Collect into a serializable form.
197	        let entries: Vec<(SerializableCacheKey, SourceData)> =
198	            self.store.iter().map(|r| (SerializableCacheKey::from(r.key()), r.value().clone())).collect();
199	
200	        let bytes = rmp_serde::to_vec(&entries).map_err(|e| e.to_string())?;
201	
202	        // Atomic write: write to tmp then rename (avoids half-written files on crash).
203	        let tmp_path = self.cache_dir.join("dts-v1.msgpack.tmp");
204	        let final_path = self.cache_dir.join("dts-v1.msgpack");
205	        std::fs::write(tmp_path.as_std_path(), &bytes).map_err(|e| e.to_string())?;
206	        std::fs::rename(tmp_path.as_std_path(), final_path.as_std_path()).map_err(|e| e.to_string())?;
