        .into_iter()
        .filter_map(|lib_file| {
            let specifier = format!("typescript/lib/{lib_file}");
            resolver.resolve(from_dir.as_std_path(), &specifier).ok().map(|r| r.path().to_string_lossy().into_owned())
        })
        .collect()
}

